begin;
insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'f8cad547-83d3-4e0b-a425-6b13fc4dda69', encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Conservation, dissipation and efficiency', 'A hairdryer is supplied with 1200 J of energy each second and transfers 900 J usefully. How much energy is wasted each second?', '0.75 J', '900 J', '300 J', '2100 J', 'C', 'Wasted energy = total input − useful output = 1200 − 900 = 300 J. 0.75 is the efficiency, not an energy.', 'foundation', 'calculation', 'AO2'),
  (2, 'Conservation, dissipation and efficiency', 'Which of these would reduce unwanted energy transfers in a machine with moving parts?', 'Removing the outer casing', 'Lubricating the moving parts', 'Using thinner connecting wires', 'Running the machine faster', 'B', 'Lubrication reduces friction between moving parts, so less energy is dissipated as thermal energy.', 'foundation', 'recall', 'AO1'),
  (3, 'Conservation, dissipation and efficiency', 'How does making a brick wall thicker affect the rate of energy transfer through it?', 'The rate of energy transfer decreases', 'The rate of energy transfer increases', 'The rate of energy transfer is unchanged', 'The wall''s thermal conductivity increases', 'A', 'A thicker wall means energy has further to travel by conduction, so the rate of transfer is lower. Thermal conductivity is a property of the material and does not change.', 'foundation', 'recall', 'AO1'),
  (4, 'Conservation, dissipation and efficiency', 'A motor has an efficiency of 0.40. Its useful energy output is 200 J. How much energy is supplied to it?', '500 J', '80 J', '240 J', '800 J', 'A', 'Total input = useful output ÷ efficiency = 200 ÷ 0.40 = 500 J. Multiplying instead gives 80 J.', 'higher', 'calculation', 'AO2'),
  (5, 'Energy stores and calculating energy changes', 'A 0.20 kg ball is thrown straight up at 10 m/s. Ignoring air resistance, what is the maximum height it reaches? (g = 9.8 N/kg)', '10 m', '1.0 m', '5.1 m', '51 m', 'C', 'Ek = ½ × 0.20 × 10² = 10 J. At the top all of this is in the gravitational store: h = Ep ÷ (mg) = 10 ÷ (0.20 × 9.8) = 5.1 m.', 'higher', 'calculation', 'AO2'),
  (6, 'Energy stores and calculating energy changes', 'A car doubles its speed. What happens to the energy in its kinetic energy store?', 'It becomes half as large', 'It becomes four times as large', 'It becomes twice as large', 'It stays exactly the same', 'B', 'Ek = ½mv², so kinetic energy depends on speed squared: doubling the speed multiplies Ek by 2² = 4.', 'foundation', 'applied', 'AO3'),
  (7, 'Energy stores and calculating energy changes', 'An archer pulls back a bow string before firing. Which energy store increases as the string is pulled back?', 'Kinetic', 'Nuclear', 'Gravitational potential', 'Elastic potential', 'D', 'Stretching (deforming) the bow stores energy in its elastic potential store. This becomes kinetic energy of the arrow when it is released.', 'foundation', 'recall', 'AO1'),
  (8, 'National and global energy resources', 'Why is a gas-fired power station useful when the demand for electricity rises suddenly?', 'It releases no carbon dioxide', 'It has no fuel costs to pay', 'It has a short start-up time', 'It uses a renewable fuel', 'C', 'Gas power stations have short start-up times, so they can meet sudden increases in demand. Burning gas does release carbon dioxide and the fuel must be paid for.', 'foundation', 'recall', 'AO1'),
  (9, 'National and global energy resources', 'Which of these renewable energy resources is the most predictable?', 'Tidal', 'Wind', 'Wave', 'Solar', 'A', 'Tides happen at times that can be predicted well in advance. Wind, waves and sunlight depend on the weather.', 'foundation', 'recall', 'AO1'),
  (10, 'National and global energy resources', 'What is a major environmental problem caused by burning coal in power stations?', 'It releases carbon dioxide and sulfur dioxide', 'It produces long-lived radioactive waste', 'It floods large areas of land behind a dam', 'It disturbs habitats on the sea bed', 'A', 'Burning coal releases carbon dioxide (which contributes to climate change) and sulfur dioxide (which causes acid rain).', 'foundation', 'recall', 'AO1'),
  (11, 'National and global energy resources', 'Hydroelectric power stations usually need a dam. What is an environmental disadvantage of this?', 'It produces radioactive waste', 'It releases a lot of carbon dioxide', 'Flooding a valley destroys habitats', 'It causes acid rain from emissions', 'C', 'Building a dam floods the land behind it, destroying habitats. Generating hydroelectricity does not release carbon dioxide or radioactive waste.', 'foundation', 'recall', 'AO1'),
  (12, 'Power', 'A 1.5 kW kettle is switched on for 2.0 minutes. How much energy does it transfer?', '180 000 J', '18 000 J', '3000 J', '180 J', 'A', 'E = Pt = 1500 W × 120 s = 180 000 J. Using 2.0 minutes instead of 120 s gives 3000 J; leaving the power in kW gives 180 J.', 'foundation', 'calculation', 'AO2'),
  (13, 'Power', 'Which of these is equal to one watt?', 'One joule per minute', 'One joule per second', 'One coulomb per second', 'One newton per metre', 'B', 'Power is the rate of energy transfer: 1 W = 1 J/s. One coulomb per second is one ampere.', 'foundation', 'recall', 'AO1'),
  (14, 'Power', 'A crane lifts a 500 kg load through 12 m in 30 s. What is its useful power output? (g = 9.8 N/kg)', '58 800 W', '5880 W', '1960 W', '200 W', 'C', 'Energy transferred = mgh = 500 × 9.8 × 12 = 58 800 J. Power = 58 800 ÷ 30 = 1960 W.', 'higher', 'calculation', 'AO2'),
  (15, 'Power', 'A motor has a power of 250 W. How long does it take to transfer 5000 J of energy?', '50 s', '2 s', '200 s', '20 s', 'D', 't = E ÷ P = 5000 ÷ 250 = 20 s.', 'foundation', 'calculation', 'AO2'),
  (16, 'Power', 'Two motors lift identical loads through the same height. Motor A takes 4 s and motor B takes 8 s. Which statement is correct?', 'Motor A has twice the power of motor B', 'Motor B has twice the power of motor A', 'Motor A does twice as much work', 'Both motors have the same power', 'A', 'Both do the same work (same load, same height), but A does it in half the time, so A''s power is twice B''s.', 'foundation', 'applied', 'AO3'),
  (17, 'Specific heat capacity', 'Water has a specific heat capacity of 4200 J/kg °C and oil has 2000 J/kg °C. Equal masses of each are given the same amount of energy. Which statement is correct?', 'The water''s temperature rises more', 'The oil''s temperature rises more', 'The water''s temperature falls instead', 'Both temperatures rise by the same amount', 'B', 'Δθ = ΔE ÷ (mc). Oil has the smaller specific heat capacity, so its temperature rises more for the same energy and mass.', 'foundation', 'applied', 'AO3'),
  (18, 'Specific heat capacity', '0.50 kg of water is supplied with 21 000 J of energy. By how much does its temperature rise? (specific heat capacity of water = 4200 J/kg °C)', '5 °C', '10 °C', '2.5 °C', '20 °C', 'B', 'Δθ = ΔE ÷ (mc) = 21 000 ÷ (0.50 × 4200) = 10 °C.', 'foundation', 'calculation', 'AO2'),
  (19, 'Specific heat capacity', 'A student finds the specific heat capacity of a metal block. Which measurement does she NOT need?', 'The mass of the block', 'The energy supplied', 'The volume of the block', 'The temperature change', 'C', 'c = ΔE ÷ (m Δθ), so she needs the energy, the mass and the temperature change, but not the volume.', 'foundation', 'recall', 'AO1'),
  (20, 'Specific heat capacity', 'In a specific heat capacity experiment, the value calculated is higher than the true value. What is the most likely reason?', 'The mass used was measured too large', 'Energy was lost to the surroundings', 'The joulemeter reading was too low', 'The temperature rise was measured too high', 'B', 'If energy is lost, the temperature rise is smaller than it should be, so ΔE ÷ (mΔθ) comes out too big. The other three would all make the value too low.', 'higher', 'applied', 'AO3'),
  (21, 'Charge and current', 'What is the unit of electric charge?', 'Volt', 'Ampere', 'Ohm', 'Coulomb', 'D', 'Charge is measured in coulombs (C). Current is in amperes, potential difference in volts and resistance in ohms.', 'foundation', 'recall', 'AO1'),
  (22, 'Charge and current', 'A charge of 120 C flows through a lamp in 1 minute. What is the current?', '120 A', '0.50 A', '7200 A', '2.0 A', 'D', 'I = Q ÷ t = 120 ÷ 60 = 2.0 A. Remember to convert 1 minute to 60 s.', 'foundation', 'calculation', 'AO2'),
  (23, 'Charge and current', 'Which of these is needed for a current to flow in a circuit?', 'A magnet held close to the wires in the circuit', 'A closed circuit with no source of potential difference', 'An open circuit and a source of potential difference', 'A closed circuit and a source of potential difference', 'D', 'Charge only flows if there is a complete (closed) loop and something, such as a cell, providing a potential difference.', 'foundation', 'recall', 'AO1'),
  (24, 'Charge and current', 'A current of 0.25 A flows for 4.0 hours. How much charge flows?', '60 C', '1.0 C', '14 400 C', '3600 C', 'D', 't = 4.0 × 3600 = 14 400 s. Q = It = 0.25 × 14 400 = 3600 C.', 'higher', 'calculation', 'AO2'),
  (25, 'Charge and current', 'In a metal wire, which particles move to carry the current?', 'Neutrons', 'Electrons', 'Positive ions', 'Protons', 'B', 'In metals, current is a flow of free (delocalised) electrons. The positive ions stay fixed in the lattice.', 'foundation', 'recall', 'AO1'),
  (26, 'Domestic uses and safety', 'What is the frequency of the UK mains supply?', '13 Hz', '60 Hz', '230 Hz', '50 Hz', 'D', 'UK mains is an alternating supply at 50 Hz and about 230 V.', 'foundation', 'recall', 'AO1'),
  (27, 'Domestic uses and safety', 'What is the purpose of the earth wire in an appliance with a metal case?', 'To stop the case becoming live if there is a fault', 'To complete the circuit when it is switched on', 'To carry the current back to the supply', 'To raise the potential difference of the supply', 'A', 'The earth wire only carries current if there is a fault; it stops the metal case becoming live. The neutral wire completes the circuit normally.', 'foundation', 'recall', 'AO1'),
  (28, 'Domestic uses and safety', 'What is the potential difference of the neutral wire?', 'About 230 V', 'About 12 V', 'About 50 V', 'About 0 V', 'D', 'The neutral wire is at or close to earth potential (0 V). The live wire is at about 230 V.', 'foundation', 'recall', 'AO1'),
  (29, 'Domestic uses and safety', 'What colour is the earth wire in a three-core mains cable?', 'Red/black', 'Brown', 'Blue', 'Green/yellow', 'D', 'Earth is green and yellow, live is brown and neutral is blue.', 'foundation', 'recall', 'AO1'),
  (30, 'Domestic uses and safety', 'What is the difference between direct and alternating potential difference?', 'Alternating pd reverses direction; direct pd does not', 'Direct pd is what the mains supplies to homes', 'Alternating pd is bigger than direct pd', 'Direct pd reverses direction; alternating pd does not', 'A', 'An alternating pd keeps changing direction (50 times a second for UK mains). A direct pd, such as from a cell, stays in one direction.', 'foundation', 'recall', 'AO1'),
  (31, 'Power, energy transfers and the National Grid', 'A 230 V heater draws a current of 8.0 A. How much energy does it transfer in 60 s?', '1840 J', '110 400 J', '480 J', '13 800 J', 'B', 'P = VI = 230 × 8.0 = 1840 W. E = Pt = 1840 × 60 = 110 400 J.', 'higher', 'calculation', 'AO2'),
  (32, 'Power, energy transfers and the National Grid', 'Why are step-down transformers used before electricity reaches homes?', 'To reduce the pd to a safer level for use', 'To change alternating current to direct current', 'To increase the frequency of the supply', 'To reduce energy losses in the cables', 'A', 'Step-down transformers reduce the very high transmission pd to about 230 V so it is safe to use. Step-up transformers are the ones that reduce cable losses.', 'foundation', 'recall', 'AO1'),
  (33, 'Power, energy transfers and the National Grid', 'Which equation links power, current and resistance?', 'P = I²R', 'P = R ÷ I²', 'P = IR²', 'P = I ÷ R', 'A', 'P = I²R. It comes from P = VI with V = IR.', 'foundation', 'recall', 'AO1'),
  (34, 'Power, energy transfers and the National Grid', 'A 9.0 V battery moves 20 C of charge around a circuit. How much energy is transferred?', '0.45 J', '29 J', '2.2 J', '180 J', 'D', 'E = QV = 20 × 9.0 = 180 J.', 'foundation', 'calculation', 'AO2'),
  (35, 'Resistance and I-V characteristics', 'A lamp has a potential difference of 6.0 V across it and a current of 0.30 A through it. What is its resistance?', '20 Ω', '1.8 Ω', '6.3 Ω', '0.050 Ω', 'A', 'R = V ÷ I = 6.0 ÷ 0.30 = 20 Ω. Multiplying gives 1.8 Ω.', 'foundation', 'calculation', 'AO2'),
  (36, 'Resistance and I-V characteristics', 'What does the I–V graph of a resistor at constant temperature look like?', 'A line that is flat in one direction', 'A curve that gets less steep', 'A straight line through the origin', 'A curve that gets steeper and steeper', 'C', 'At constant temperature the current is directly proportional to the potential difference (an ohmic conductor), giving a straight line through the origin.', 'foundation', 'recall', 'AO1'),
  (37, 'Resistance and I-V characteristics', 'How does the resistance of a light-dependent resistor (LDR) change as the light gets brighter?', 'It reverses direction', 'It stays the same', 'It decreases', 'It increases', 'C', 'An LDR''s resistance falls as light intensity increases, which is why LDRs are used in circuits that switch lights on when it gets dark.', 'foundation', 'recall', 'AO1'),
  (38, 'Resistance and I-V characteristics', 'In the resistance of a wire practical, how does the resistance change as the length of wire increases?', 'It increases in proportion to the length', 'It does not change with length', 'It decreases in proportion to the length', 'It increases at first then levels off', 'A', 'Resistance is directly proportional to the length of the wire: double the length, double the resistance.', 'foundation', 'recall', 'AO1'),
  (39, 'Series and parallel circuits', 'Two resistors are connected in parallel across a 6.0 V battery. What is the potential difference across each resistor?', '3.0 V', '0 V', '6.0 V', '12 V', 'C', 'Components in parallel each have the same potential difference across them as the supply.', 'foundation', 'recall', 'AO1'),
  (40, 'Series and parallel circuits', 'In a parallel circuit, the currents in the two branches are 0.20 A and 0.30 A. What is the current from the supply?', '0.10 A', '0.25 A', '0.060 A', '0.50 A', 'D', 'The total current in a parallel circuit is the sum of the branch currents: 0.20 + 0.30 = 0.50 A.', 'foundation', 'calculation', 'AO2'),
  (41, 'Series and parallel circuits', 'Why is the total resistance of two resistors in parallel less than the resistance of the smaller resistor?', 'The potential difference across each resistor is halved', 'The current in each branch is the same', 'The resistors share the total charge equally', 'There are more paths for the current to flow through', 'D', 'Adding a parallel branch gives charge another path, so more current flows for the same pd and the total resistance falls.', 'higher', 'applied', 'AO3'),
  (42, 'Series and parallel circuits', 'A 2 Ω, a 3 Ω and a 5 Ω resistor are connected in series to a 20 V supply. What is the current?', '2.0 A', '200 A', '0.50 A', '10 A', 'A', 'Total resistance = 2 + 3 + 5 = 10 Ω. I = V ÷ R = 20 ÷ 10 = 2.0 A.', 'foundation', 'calculation', 'AO2'),
  (43, 'Static electricity', 'What happens when two objects with opposite charges are brought close together?', 'They attract', 'They repel', 'They lose charge', 'They become neutral', 'A', 'Opposite charges attract; like charges repel. This is a non-contact force.', 'foundation', 'recall', 'AO1'),
  (44, 'Static electricity', 'A charged balloon sticks to a neutral wall. Why?', 'The wall already has a strong positive charge', 'Rubbing made the balloon into a magnet', 'It induces an opposite charge on the wall''s surface', 'Protons from the wall flow onto the balloon', 'C', 'The balloon''s charge repels or attracts electrons in the wall, leaving the nearby surface oppositely charged, so the balloon is attracted.', 'higher', 'applied', 'AO3'),
  (45, 'Static electricity', 'What is an electric field?', 'The path the current takes in a wire', 'The energy stored by a charged object', 'A region where a magnet feels a force', 'A region where a charge feels a force', 'D', 'A charged object creates an electric field around it. Any other charge placed in the field experiences a force.', 'foundation', 'recall', 'AO1'),
  (46, 'Static electricity', 'How does the electric field around a charged sphere change as you move further away from it?', 'It gets weaker', 'It gets stronger', 'It reverses direction', 'It stays the same', 'A', 'The electric field is strongest close to the charged object and gets weaker with distance.', 'foundation', 'recall', 'AO1'),
  (47, 'Static electricity', 'Why can a spark jump from a highly charged object to an earthed conductor close to it?', 'The object''s magnetic field collapses', 'Protons flow through the air to earth', 'The strong electric field ionises the air', 'The air conducts well when it is cold', 'C', 'A strong enough electric field ionises air molecules, making a conducting path; electrons then flow through the air as a spark.', 'higher', 'applied', 'AO3'),
  (48, 'Static electricity', 'A rod is rubbed with a cloth and becomes positively charged. What has happened?', 'Protons have moved from the cloth to the rod', 'Electrons have moved from the rod to the cloth', 'Electrons have moved from the cloth to the rod', 'Protons have moved from the rod to the cloth', 'B', 'Only electrons move when objects are rubbed. The rod lost electrons, leaving it with an overall positive charge.', 'foundation', 'applied', 'AO2'),
  (49, 'Density and changes of state', 'A liquid has a density of 800 kg/m³. What is the mass of 0.050 m³ of the liquid?', '400 kg', '40 kg', '4.0 kg', '16 kg', 'B', 'm = ρV = 800 × 0.050 = 40 kg.', 'foundation', 'calculation', 'AO2'),
  (50, 'Atoms, isotopes and the development of the atomic model', 'What did the alpha particle scattering experiment show?', 'Atoms are solid spheres that cannot be divided', 'Neutrons orbit the nucleus in fixed energy levels', 'Most of an atom''s mass is in a tiny, positive nucleus', 'Electrons are spread through a ball of positive charge', 'C', 'Most alpha particles passed straight through but a few bounced back, so the mass and positive charge must be concentrated in a tiny nucleus. This replaced the plum pudding model.', 'foundation', 'recall', 'AO1'),
  (51, 'Atoms, isotopes and the development of the atomic model', 'Which particle did James Chadwick provide evidence for?', 'The proton', 'The neutron', 'The electron', 'The nucleus', 'B', 'About 20 years after the nucleus was discovered, Chadwick''s experiments showed the existence of neutrons.', 'foundation', 'recall', 'AO1'),
  (52, 'Atoms, isotopes and the development of the atomic model', 'What are isotopes of an element?', 'Atoms with different numbers of both protons and electrons', 'Atoms with the same number of neutrons but different numbers of protons', 'Atoms with the same number of protons but different numbers of neutrons', 'Atoms with the same mass number but different numbers of electrons', 'C', 'Isotopes are the same element (same number of protons) with different mass numbers because they have different numbers of neutrons.', 'foundation', 'recall', 'AO1'),
  (53, 'Background radiation, uses of radiation, fission and fusion', 'Which of these is a man-made source of background radiation?', 'Rocks such as granite', 'Nuclear weapons test fallout', 'Cosmic rays from outer space', 'Radon gas from the ground', 'B', 'Fallout from weapons testing and nuclear accidents is man-made. Cosmic rays, radon and rocks are natural sources.', 'foundation', 'recall', 'AO1'),
  (54, 'Background radiation, uses of radiation, fission and fusion', 'Why is the radiation dose from radon gas different in different parts of the UK?', 'It depends on the height of the buildings', 'It depends on how many people live there', 'It depends on how close the area is to the sea', 'It depends on the type of rock in the area', 'D', 'Radon is released by certain rocks, such as granite, so areas built on those rocks have higher doses.', 'foundation', 'recall', 'AO1'),
  (55, 'Background radiation, uses of radiation, fission and fusion', 'Why are very high temperatures and pressures needed for nuclear fusion?', 'To slow down the neutrons that are released', 'To overcome the repulsion between positive nuclei', 'To absorb the gamma rays that are given out', 'To split heavy nuclei into smaller nuclei', 'B', 'Nuclei are positively charged and repel each other. They must be moving very fast and be very close together to fuse.', 'higher', 'applied', 'AO3'),
  (56, 'Half-life, contamination and irradiation', 'A sample has a count rate of 640 counts per minute. What will the count rate be after 3 half-lives? (Ignore background radiation.)', '160 counts per minute', '213 counts per minute', '320 counts per minute', '80 counts per minute', 'D', 'Halve three times: 640 → 320 → 160 → 80. Dividing by 3 gives 213, which is wrong.', 'foundation', 'calculation', 'AO2'),
  (57, 'Half-life, contamination and irradiation', 'The activity of a source falls from 400 Bq to 100 Bq in 12 days. What is its half-life?', '6 days', '3 days', '4 days', '12 days', 'A', '400 → 200 → 100 is two half-lives, so one half-life = 12 ÷ 2 = 6 days.', 'foundation', 'calculation', 'AO2'),
  (58, 'Half-life, contamination and irradiation', 'Why are isotopes with short half-lives chosen as medical tracers?', 'They are more penetrating than long-lived isotopes', 'They emit alpha particles, which are easy to detect', 'Their activity falls quickly, so the patient''s dose is lower', 'They stay radioactive inside the body for many years', 'C', 'A short half-life means the source is only active for a short time, so the patient is exposed to less radiation.', 'foundation', 'applied', 'AO3'),
  (59, 'Radioactive decay, nuclear radiation and nuclear equations', 'What is an alpha particle?', 'A single neutron from the nucleus', 'Two protons and two neutrons', 'A fast-moving electron', 'A high-frequency electromagnetic wave', 'B', 'An alpha particle is the same as a helium nucleus: two protons and two neutrons.', 'foundation', 'recall', 'AO1'),
  (60, 'Radioactive decay, nuclear radiation and nuclear equations', 'Carbon-14 (atomic number 6) decays by emitting a beta particle. What is the atomic number of the new nucleus?', '5', '6', '4', '7', 'D', 'In beta decay a neutron becomes a proton, so the atomic number goes up by 1 and the mass number stays the same.', 'foundation', 'applied', 'AO2'),
  (61, 'Radioactive decay, nuclear radiation and nuclear equations', 'Radioactive decay is random. What does this mean?', 'You cannot predict which nucleus will decay next', 'Half of the nuclei decay each second', 'Decay can be sped up by heating the sample', 'The nuclei in a sample decay at the same moment', 'A', 'You can''t say when a particular nucleus will decay, but you can predict how a large number of nuclei will behave on average (half-life).', 'foundation', 'recall', 'AO1'),
  (62, 'Describing motion: speed, velocity, acceleration and graphs', 'What does the gradient of a distance–time graph represent?', 'Distance', 'Acceleration', 'Resultant force', 'Speed', 'D', 'Gradient = change in distance ÷ change in time = speed. The gradient of a velocity–time graph is acceleration.', 'foundation', 'recall', 'AO1'),
  (63, 'Describing motion: speed, velocity, acceleration and graphs', 'A cyclist slows down from 12 m/s to 4.0 m/s in 2.0 s. What is the deceleration?', '6.0 m/s²', '2.0 m/s²', '4.0 m/s²', '8.0 m/s²', 'C', 'a = Δv ÷ t = (12 − 4.0) ÷ 2.0 = 4.0 m/s² (a deceleration).', 'foundation', 'calculation', 'AO2'),
  (64, 'Describing motion: speed, velocity, acceleration and graphs', 'What is the difference between speed and velocity?', 'Velocity is speed in a given direction', 'Velocity is bigger than speed', 'Speed is velocity in a given direction', 'Speed is measured in metres per second squared', 'A', 'Speed is a scalar; velocity is a vector, so it has a direction as well as a size.', 'foundation', 'recall', 'AO1'),
  (65, 'Describing motion: speed, velocity, acceleration and graphs', 'What is a typical walking speed for a person?', '0.15 m/s', '15 m/s', '1.5 m/s', '6.0 m/s', 'C', 'Typical speeds: walking about 1.5 m/s, running about 3 m/s, cycling about 6 m/s.', 'foundation', 'recall', 'AO1'),
  (66, 'Forces and elasticity', 'A spring stretches by 0.040 m when a 2.0 N force is applied. What is its spring constant?', '8.0 N/m', '50 N/m', '20 N/m', '0.080 N/m', 'B', 'k = F ÷ e = 2.0 ÷ 0.040 = 50 N/m. Multiplying gives 0.080.', 'foundation', 'calculation', 'AO2'),
  (67, 'Forces and elasticity', 'Why is more than one force needed to stretch, bend or squash an object?', 'Objects change shape when they are heated', 'One force would compress it instead', 'One force cannot do any work on it', 'With one force the object would just move', 'D', 'With a single force there is a resultant force, so the object accelerates instead of changing shape. Stretching needs forces in opposite directions.', 'foundation', 'applied', 'AO3'),
  (68, 'Forces and elasticity', 'What is inelastic deformation?', 'The object does not return to its original shape', 'The object returns to its original shape', 'The object stretches with no force', 'The object breaks cleanly into two pieces', 'A', 'After inelastic deformation the object stays permanently stretched or bent when the forces are removed.', 'foundation', 'recall', 'AO1'),
  (69, 'Forces and elasticity', 'A spring with a spring constant of 25 N/m is stretched by 0.20 m. How much elastic potential energy is stored? (elastic potential energy = 0.5 × spring constant × extension²)', '2.5 J', '5.0 J', '0.25 J', '0.50 J', 'D', 'Ee = ½ke² = 0.5 × 25 × 0.20² = 0.5 × 25 × 0.040 = 0.50 J. Forgetting to square gives 2.5 J.', 'higher', 'calculation', 'AO2'),
  (70, 'Forces and elasticity', 'A graph of force against extension for a spring is a straight line through the origin. What does this show?', 'Extension is inversely proportional to force', 'Extension is directly proportional to force', 'The spring constant increases with the force', 'The spring has passed its limit of proportionality', 'B', 'A straight line through the origin means the spring obeys Hooke''s law, F = ke.', 'foundation', 'applied', 'AO3'),
  (71, 'Moments, levers and gears', 'What is the unit of a moment?', 'Newton per metre (N/m)', 'Joule per metre (J/m)', 'Newton-metre (N m)', 'Newton (N)', 'C', 'Moment = force × perpendicular distance, so its unit is N m.', 'foundation', 'recall', 'AO1'),
  (72, 'Moments, levers and gears', 'Why is it easier to open a door by pushing near the handle than near the hinge?', 'A bigger distance from the pivot gives a bigger moment', 'Friction at the hinge is lower near the handle', 'A bigger distance from the pivot gives a smaller moment', 'The door''s weight is smaller near the handle', 'A', 'The hinge is the pivot. Pushing further from it increases the moment for the same force, so less force is needed.', 'foundation', 'applied', 'AO3'),
  (73, 'Moments, levers and gears', 'A 5.0 N force acts 0.40 m from a pivot. What force, acting 0.10 m from the pivot on the other side, would balance it?', '20 N', '0.50 N', '2.0 N', '1.25 N', 'A', 'Clockwise moment = anticlockwise moment: 5.0 × 0.40 = F × 0.10, so F = 2.0 ÷ 0.10 = 20 N.', 'foundation', 'calculation', 'AO2'),
  (74, 'Moments, levers and gears', 'What does the principle of moments state?', 'For a balanced object, the distances on each side of the pivot are equal', 'For a balanced object, there is no force acting on the pivot', 'For a balanced object, the forces on each side of the pivot are equal', 'For a balanced object, total clockwise moment equals total anticlockwise moment', 'D', 'If an object is balanced, the sum of the clockwise moments about the pivot equals the sum of the anticlockwise moments.', 'foundation', 'recall', 'AO1'),
  (75, 'Moments, levers and gears', 'A small gear with 10 teeth drives a large gear with 40 teeth. How does the large gear turn compared with the small gear?', 'Faster, with a bigger moment', 'More slowly, with a smaller moment', 'At the same speed and moment', 'More slowly, with a bigger moment', 'D', 'A larger driven gear turns more slowly but the force acts at a bigger radius, so it gives a bigger moment.', 'higher', 'applied', 'AO3'),
  (76, 'Momentum', 'What is the unit of momentum?', 'kg m/s', 'kg m/s²', 'J/s', 'N/m', 'A', 'Momentum = mass × velocity, so its unit is kg m/s.', 'foundation', 'recall', 'AO1'),
  (77, 'Momentum', 'What does conservation of momentum mean?', 'In a closed system, heavier objects keep their momentum', 'In a closed system, total kinetic energy is the same after', 'In a closed system, total momentum before equals total momentum after', 'In a closed system, total momentum after a collision is zero', 'C', 'In a closed system the total momentum before an event (such as a collision or explosion) equals the total momentum after.', 'foundation', 'recall', 'AO1'),
  (78, 'Momentum', 'Two skaters stand still on ice, then push apart. The 60 kg skater moves off at 2.0 m/s. How fast does the 40 kg skater move?', '3.0 m/s', '1.3 m/s', '2.0 m/s', '5.0 m/s', 'A', 'Total momentum before is zero, so the skaters have equal and opposite momentum after: 60 × 2.0 = 40 × v, so v = 120 ÷ 40 = 3.0 m/s.', 'higher', 'calculation', 'AO2'),
  (79, 'Momentum', 'A force of 200 N acts on a ball for 0.050 s. What is the change in the ball''s momentum?', '0.25 kg m/s', '4000 kg m/s', '40 kg m/s', '10 kg m/s', 'D', 'Force = rate of change of momentum, so change in momentum = F × t = 200 × 0.050 = 10 kg m/s.', 'higher', 'calculation', 'AO2'),
  (80, 'Momentum', 'Why do crash mats in a gym reduce injuries?', 'They reduce the gymnast''s mass as they land on them', 'They increase the time taken to stop, so the force is larger', 'They increase the time taken to stop, so the force is smaller', 'They reduce the gymnast''s momentum before they land', 'C', 'The change of momentum is the same, but it happens over a longer time, so the rate of change of momentum (the force) is smaller.', 'foundation', 'applied', 'AO3'),
  (81, 'Momentum', 'A 1500 kg car moves at 20 m/s. What is its momentum?', '75 kg m/s', '3000 kg m/s', '300 000 kg m/s', '30 000 kg m/s', 'D', 'p = mv = 1500 × 20 = 30 000 kg m/s.', 'foundation', 'calculation', 'AO2'),
  (82, 'Newton''s laws of motion', 'What does Newton''s first law say about an object with zero resultant force on it?', 'It speeds up in its direction of motion', 'It slows down until it eventually stops', 'It stays at rest or moves at a constant velocity', 'It changes direction but keeps its speed', 'C', 'If the resultant force is zero, a stationary object stays still and a moving object keeps the same speed in the same direction.', 'foundation', 'recall', 'AO1'),
  (83, 'Newton''s laws of motion', 'A 5.0 kg trolley has a resultant force of 15 N on it. What is its acceleration?', '10 m/s²', '75 m/s²', '0.33 m/s²', '3.0 m/s²', 'D', 'a = F ÷ m = 15 ÷ 5.0 = 3.0 m/s².', 'foundation', 'calculation', 'AO2'),
  (84, 'Newton''s laws of motion', 'What is inertia?', 'The tendency of an object to stay at rest or keep moving uniformly', 'The force needed to keep an object moving at a steady speed', 'The total momentum of the moving parts of an object', 'The rate at which an object speeds up when pushed', 'A', 'Inertia is the tendency to keep the same motion. Inertial mass measures how hard it is to change an object''s velocity.', 'higher', 'recall', 'AO1'),
  (85, 'Newton''s laws of motion', 'A box falls through the air at terminal velocity. Which statement is correct?', 'The air resistance is greater than its weight', 'Its weight equals the air resistance on it', 'There are no forces acting on the box', 'Its weight is greater than the air resistance', 'B', 'At terminal velocity the forces are balanced, so the resultant force is zero and the velocity stays constant.', 'foundation', 'applied', 'AO2'),
  (86, 'Newton''s laws of motion', 'In the acceleration practical, the resultant force on a trolley is doubled and its mass is kept the same. What happens to its acceleration?', 'It quadruples', 'It stays the same', 'It doubles', 'It halves', 'C', 'a = F ÷ m, so acceleration is directly proportional to resultant force when the mass is constant.', 'foundation', 'applied', 'AO2'),
  (87, 'Pressure in fluids', 'What is the unit of pressure?', 'Pascal (Pa)', 'Joule (J)', 'Newton-metre (N m)', 'Newton (N)', 'A', 'Pressure = force ÷ area, measured in pascals. 1 Pa = 1 N/m².', 'foundation', 'recall', 'AO1'),
  (88, 'Pressure in fluids', 'Why does atmospheric pressure decrease as you go higher above the ground?', 'The air particles move much faster higher up', 'There is more air above pushing down', 'There is less air above, so less weight of air', 'Gravity is much stronger higher up', 'C', 'Higher up there is less air above you, so the weight of air pushing down on each square metre is smaller. The air is also less dense.', 'foundation', 'applied', 'AO3'),
  (89, 'Pressure in fluids', 'An object floats in water. What is true about the upthrust on it?', 'It is greater than the object''s weight', 'It is zero because the object floats', 'It is equal to the object''s weight', 'It is less than the object''s weight', 'C', 'A floating object is in equilibrium: the upthrust balances its weight.', 'foundation', 'applied', 'AO2'),
  (90, 'Pressure in fluids', 'What is the pressure due to a 2.0 m column of a liquid with a density of 1200 kg/m³? (pressure = height × density × g, g = 9.8 N/kg)', '235 200 Pa', '23 520 Pa', '2400 Pa', '6000 Pa', 'B', 'p = hρg = 2.0 × 1200 × 9.8 = 23 520 Pa. Leaving out g gives 2400 Pa.', 'higher', 'calculation', 'AO2'),
  (91, 'Pressure in fluids', 'Why is a dam built thicker at the bottom than at the top?', 'Air pressure pushes harder on the bottom', 'Water pressure is greatest at the surface', 'Water pressure is greater at greater depth', 'The water is denser near the surface', 'C', 'Pressure in a liquid increases with depth, so the bottom of the dam has the largest force on it.', 'foundation', 'applied', 'AO3'),
  (92, 'Pressure in fluids', 'In which direction does the pressure in a fluid act on a surface?', 'Parallel to the surface', 'At right angles to the surface', 'Straight down onto the surface', 'Straight up from the surface', 'B', 'The pressure in a fluid causes a force at right angles (normal) to any surface it touches.', 'foundation', 'recall', 'AO1'),
  (93, 'Scalars, vectors, weight and resultant forces', 'Which of these is a scalar quantity?', 'Weight', 'Mass', 'Velocity', 'Displacement', 'B', 'A scalar has size only. Weight is a force, so it is a vector; velocity and displacement are vectors too.', 'foundation', 'recall', 'AO1'),
  (94, 'Scalars, vectors, weight and resultant forces', 'What is the weight of a 2.0 kg bag on the Moon, where g = 1.6 N/kg?', '1.25 N', '3.2 N', '2.0 N', '19.6 N', 'B', 'W = mg = 2.0 × 1.6 = 3.2 N. Its mass is still 2.0 kg.', 'foundation', 'calculation', 'AO2'),
  (95, 'Scalars, vectors, weight and resultant forces', 'A 3.0 N force acts north and a 4.0 N force acts east on an object. What is the size of the resultant force?', '12 N', '5.0 N', '1.0 N', '7.0 N', 'B', 'The forces are at right angles: resultant = √(3.0² + 4.0²) = 5.0 N. You could also find this with a scale drawing.', 'foundation', 'calculation', 'AO2'),
  (96, 'Scalars, vectors, weight and resultant forces', 'What is the centre of mass of an object?', 'The point where friction acts on it', 'The point where its mass is greatest', 'The point at the bottom of the object', 'The point where its weight acts', 'D', 'The weight of an object can be thought of as acting at a single point, its centre of mass.', 'foundation', 'recall', 'AO1'),
  (97, 'Scalars, vectors, weight and resultant forces', 'How is the weight of an object related to its mass?', 'Weight does not depend on mass', 'Weight and mass are the same quantity', 'Weight is inversely proportional to mass', 'Weight is directly proportional to mass', 'D', 'W = mg, so in a given gravitational field weight is directly proportional to mass.', 'foundation', 'recall', 'AO1'),
  (98, 'Stopping distances', 'Which of these increases the braking distance of a car?', 'Drinking alcohol', 'Tiredness', 'Using a phone', 'Icy roads', 'D', 'Icy roads reduce friction between the tyres and the road. The other three increase reaction time, which affects thinking distance.', 'foundation', 'recall', 'AO1'),
  (99, 'Stopping distances', 'A car''s speed is doubled. For the same braking force, how does its braking distance change?', 'It doubles', 'It halves', 'It is unchanged', 'It quadruples', 'D', 'Work done by the brakes (F × d) must equal the kinetic energy, which depends on speed squared. Doubling speed gives 4 times the energy, so 4 times the distance.', 'higher', 'applied', 'AO3'),
  (100, 'Stopping distances', 'What is a typical reaction time for a person?', '0.2 s to 0.9 s', '2 s to 3 s', '0.01 s to 0.02 s', '5 s to 9 s', 'A', 'Most people react in between about 0.2 s and 0.9 s.', 'foundation', 'recall', 'AO1'),
  (101, 'Stopping distances', 'Why are large decelerations dangerous for the people in a car?', 'They make the car''s mass increase', 'They need large forces that injure people', 'They reduce the car''s speed too slowly', 'They make the brakes cool down too fast', 'B', 'F = ma, so a large deceleration needs a large force on the people in the car, which can injure them.', 'foundation', 'applied', 'AO3'),
  (102, 'Stopping distances', 'What happens to a car''s kinetic energy when the brakes are applied?', 'It is transferred to the elastic store of the car''s tyres', 'Work done by friction transfers it to thermal energy in the brakes', 'It is transferred to the car''s gravitational potential store', 'It is destroyed by the friction force between the brake pads', 'B', 'Friction between the brake pads and discs does work, transferring kinetic energy to the thermal store of the brakes, which heat up.', 'foundation', 'recall', 'AO1'),
  (103, 'Stopping distances', 'A car travels at 15 m/s and the driver''s reaction time is 0.60 s. What is the thinking distance?', '25 m', '15.6 m', '9.0 m', '0.040 m', 'C', 'Thinking distance = speed × reaction time = 15 × 0.60 = 9.0 m.', 'foundation', 'calculation', 'AO2'),
  (104, 'Work done and energy transfer', 'What is the unit of work done?', 'Pascal', 'Watt', 'Joule', 'Newton', 'C', 'Work done is energy transferred, so it is measured in joules (1 J = 1 N m).', 'foundation', 'recall', 'AO1'),
  (105, 'Work done and energy transfer', 'A person lifts a box with a weight of 20 N through a height of 1.5 m. How much work is done on the box?', '30 J', '13 J', '21.5 J', '300 J', 'A', 'W = Fs = 20 × 1.5 = 30 J.', 'foundation', 'calculation', 'AO2'),
  (106, 'Work done and energy transfer', 'A box is pushed across a rough floor. Work is done against friction. What happens to the box and the floor?', 'They lose some mass', 'Their temperature rises', 'They gain potential energy', 'Their temperature falls', 'B', 'Work done against friction transfers energy to the thermal store of the box and floor, so they warm up.', 'foundation', 'recall', 'AO1'),
  (107, 'Work done and energy transfer', 'How far must a 40 N force push a trolley to do 200 J of work?', '0.20 m', '5.0 m', '8000 m', '160 m', 'B', 's = W ÷ F = 200 ÷ 40 = 5.0 m.', 'foundation', 'calculation', 'AO2'),
  (108, 'Work done and energy transfer', 'Which equation links work done, force and distance moved along the line of the force?', 'W = s ÷ F', 'W = F ÷ s', 'W = F × s', 'W = F × s²', 'C', 'Work done = force × distance moved along the line of action of the force.', 'foundation', 'recall', 'AO1'),
  (109, 'Work done and energy transfer', 'A car''s driving force is 2000 N while it travels 500 m. How much work does the driving force do?', '2500 J', '1 000 000 J', '4.0 J', '250 J', 'B', 'W = Fs = 2000 × 500 = 1 000 000 J (1.0 MJ).', 'foundation', 'calculation', 'AO2'),
  (110, 'Black body radiation', 'Why does the Earth''s average temperature stay roughly constant?', 'It absorbs radiation but does not emit any', 'It absorbs and emits radiation at about the same rate', 'It emits radiation but does not absorb any', 'It neither absorbs nor emits any radiation', 'B', 'If absorption and emission happen at the same rate, there is no overall gain or loss of energy, so the temperature stays constant.', 'foundation', 'applied', 'AO3'),
  (111, 'Black body radiation', 'As an object gets hotter, what happens to the wavelength at which it emits the most radiation?', 'It becomes infinite', 'It gets shorter', 'It stays the same', 'It gets longer', 'B', 'Hotter objects emit more radiation at every wavelength and the peak moves to shorter wavelengths (e.g. red-hot to white-hot).', 'higher', 'recall', 'AO1'),
  (112, 'Black body radiation', 'Which surface is the best absorber of infrared radiation?', 'Shiny silver', 'Matt white', 'Matt black', 'Shiny white', 'C', 'Dark, matt surfaces are the best absorbers and emitters of infrared. Light, shiny surfaces are the worst.', 'foundation', 'recall', 'AO1'),
  (113, 'Black body radiation', 'An object absorbs radiation faster than it emits radiation. What happens to its temperature?', 'It stays the same', 'It increases', 'It falls to zero', 'It decreases', 'B', 'It gains energy overall, so its temperature rises.', 'foundation', 'applied', 'AO2'),
  (114, 'Black body radiation', 'Which of these affects the temperature of the Earth?', 'How far the Moon is from the Earth', 'The radiation the atmosphere absorbs and emits', 'How fast the Earth spins on its axis each day', 'How many moons orbit around the Earth', 'B', 'The Earth''s temperature depends on the balance of radiation absorbed and emitted, which depends on the atmosphere (e.g. clouds and greenhouse gases).', 'foundation', 'recall', 'AO1'),
  (115, 'Electromagnetic waves: properties, uses and hazards', 'Which type of electromagnetic wave is used to cook food quickly in an oven?', 'Microwaves', 'Gamma rays', 'Radio waves', 'Ultraviolet', 'A', 'Microwaves are absorbed by water molecules in food, heating it.', 'foundation', 'recall', 'AO1'),
  (116, 'Electromagnetic waves: properties, uses and hazards', 'Which list puts the electromagnetic spectrum in order from longest to shortest wavelength?', 'Microwave, radio, infrared, visible, X-ray, UV, gamma', 'Radio, microwave, infrared, visible, UV, X-ray, gamma', 'Gamma, X-ray, UV, visible, infrared, microwave, radio', 'Radio, infrared, microwave, visible, UV, gamma, X-ray', 'B', 'Radio waves have the longest wavelength and gamma rays the shortest.', 'foundation', 'recall', 'AO1'),
  (117, 'Electromagnetic waves: properties, uses and hazards', 'What is the speed of all electromagnetic waves in a vacuum?', '3 × 10⁴ m/s', '3 × 10⁸ m/s', '1500 m/s', '340 m/s', 'B', 'All electromagnetic waves travel at 3 × 10⁸ m/s in a vacuum. 340 m/s is the speed of sound in air.', 'foundation', 'recall', 'AO1'),
  (118, 'Electromagnetic waves: properties, uses and hazards', 'Why are X-rays and gamma rays dangerous to people?', 'They strongly heat the surface of the skin', 'They are ionising, so they damage DNA', 'They have very long wavelengths', 'They are absorbed by the skin''s surface', 'B', 'X-rays and gamma rays are ionising radiation, which can cause mutation of genes and cancer.', 'foundation', 'recall', 'AO1'),
  (119, 'Lenses', 'What is the principal focus of a convex lens?', 'The point in the exact centre of the lens itself', 'The point where rays are reflected back by the lens', 'The point where rays first enter the lens surface', 'The point where parallel rays meet after passing through it', 'D', 'Parallel rays are refracted by a convex lens and brought together at the principal focus.', 'foundation', 'recall', 'AO1'),
  (120, 'Lenses', 'A magnifying glass gives a magnification of 4. An object is 0.50 cm tall. How tall is the image?', '4.5 cm', '0.125 cm', '8.0 cm', '2.0 cm', 'D', 'Image height = magnification × object height = 4 × 0.50 = 2.0 cm.', 'foundation', 'calculation', 'AO2'),
  (121, 'Lenses', 'What is a virtual image?', 'An image that is larger than the object', 'An image that is upside down and smaller', 'An image that cannot be projected onto a screen', 'An image formed where the rays actually meet', 'C', 'A virtual image is formed where rays only appear to come from, so it cannot be shown on a screen.', 'foundation', 'recall', 'AO1'),
  (122, 'Lenses', 'What does a concave lens do to parallel rays of light?', 'Spreads them out', 'Leaves them unchanged', 'Reflects them back', 'Brings them to a point', 'A', 'A concave lens is a diverging lens: it spreads parallel rays out so they appear to come from a principal focus.', 'foundation', 'recall', 'AO1'),
  (123, 'Lenses', 'Which of these is true for a real image formed by a convex lens?', 'It cannot be seen', 'It is upright', 'It is virtual', 'It is inverted', 'D', 'Real images from a convex lens are always upside down (inverted) and can be projected onto a screen.', 'foundation', 'recall', 'AO1'),
  (124, 'Reflection, sound, ultrasound and seismic waves', 'What is the law of reflection?', 'The angle of incidence equals the angle of reflection', 'The angle of incidence is twice the angle of reflection', 'The angle of reflection is equal to 90° minus the angle of incidence', 'The angle of incidence equals the angle of refraction', 'A', 'Both angles are measured from the normal, and they are equal.', 'foundation', 'recall', 'AO1'),
  (125, 'Reflection, sound, ultrasound and seismic waves', 'Sound waves pass from air into water. What happens to them?', 'Their speed and wavelength both increase', 'Their frequency increases and wavelength decreases', 'Their speed and wavelength both decrease', 'Their speed decreases and frequency increases', 'A', 'Sound travels faster in water. The frequency stays the same, so from v = fλ the wavelength increases too.', 'higher', 'applied', 'AO3'),
  (126, 'Reflection, sound, ultrasound and seismic waves', 'Why can P-waves travel through the Earth''s outer core but S-waves cannot?', 'S-waves are longitudinal and are absorbed by rock', 'P-waves are faster, so they reach the core first', 'S-waves are transverse and cannot travel through liquids', 'The outer core is solid, which stops S-waves', 'C', 'P-waves are longitudinal and travel through solids and liquids. S-waves are transverse and only travel through solids, so the outer core must be liquid.', 'higher', 'applied', 'AO3'),
  (127, 'Reflection, sound, ultrasound and seismic waves', 'Why is ultrasound used for prenatal scans rather than X-rays?', 'It travels faster than X-rays in the body', 'It produces clearer images of bones', 'It is not ionising, so it is safer for the fetus', 'It passes easily through metal objects', 'C', 'Ultrasound is partly reflected at boundaries between tissues to build an image, and it does not ionise cells.', 'foundation', 'recall', 'AO1'),
  (128, 'Transverse and longitudinal waves and the wave equation', 'Which of these is a transverse wave?', 'A P-wave', 'Ultrasound', 'Light', 'Sound', 'C', 'All electromagnetic waves, including light, are transverse. Sound, ultrasound and P-waves are longitudinal.', 'foundation', 'recall', 'AO1'),
  (129, 'Transverse and longitudinal waves and the wave equation', 'What is the wavelength of a wave?', 'The number of waves passing a point each second', 'The distance from a point on one wave to the same point on the next', 'The maximum height of the wave from its rest position', 'The time taken for one complete wave to pass a point', 'B', 'Wavelength is the distance from one point to the equivalent point on the next wave, e.g. crest to crest.', 'foundation', 'recall', 'AO1'),
  (130, 'Transverse and longitudinal waves and the wave equation', 'A sound wave has a speed of 340 m/s and a frequency of 170 Hz. What is its wavelength?', '510 m', '57 800 m', '0.50 m', '2.0 m', 'D', 'λ = v ÷ f = 340 ÷ 170 = 2.0 m.', 'foundation', 'calculation', 'AO2'),
  (131, 'Transverse and longitudinal waves and the wave equation', 'A water wave travels across a pond. What is transferred from one side of the pond to the other?', 'Neither water nor energy', 'Both water and energy', 'Energy, but not water', 'Water, but not energy', 'C', 'Waves transfer energy. The water particles only oscillate about a fixed position.', 'foundation', 'recall', 'AO1'),
  (132, 'Visible light and colour', 'Which colour of visible light has the longest wavelength?', 'Red', 'Violet', 'Blue', 'Green', 'A', 'In the visible spectrum, red has the longest wavelength and violet the shortest.', 'foundation', 'recall', 'AO1'),
  (133, 'Visible light and colour', 'What does a green filter do to white light?', 'It absorbs green light and transmits other colours', 'It turns the white light into green light', 'It reflects green light and transmits other colours', 'It transmits green light and absorbs other colours', 'D', 'A coloured filter only lets through (transmits) its own colour and absorbs the rest.', 'foundation', 'recall', 'AO1'),
  (134, 'Visible light and colour', 'Why does a white object look white in white light?', 'It reflects all wavelengths equally', 'It gives out its own white light', 'It transmits all wavelengths', 'It absorbs all wavelengths equally', 'A', 'White objects reflect all visible wavelengths equally. Black objects absorb all of them.', 'foundation', 'recall', 'AO1'),
  (135, 'Visible light and colour', 'What is specular reflection?', 'Reflection from a rough surface in many directions', 'Light changing direction as it enters a material', 'Reflection from a smooth surface in a single direction', 'Light being absorbed by a dark, matt surface', 'C', 'Smooth surfaces give specular reflection (like a mirror). Rough surfaces scatter light: diffuse reflection.', 'foundation', 'recall', 'AO1'),
  (136, 'Visible light and colour', 'A blue object is looked at through a red filter in white light. What colour does it appear?', 'Purple', 'Blue', 'Black', 'Red', 'C', 'The object only reflects blue light, and the red filter absorbs blue light, so no light reaches the eye.', 'higher', 'applied', 'AO3'),
  (137, 'Visible light and colour', 'What happens to light that hits an opaque object?', 'None of it is transmitted', 'It is transmitted but scattered', 'Only red light is reflected', 'All of it is transmitted', 'A', 'Opaque objects do not let light pass through; the light is reflected or absorbed.', 'foundation', 'recall', 'AO1'),
  (138, 'Induced potential, generators and transformers', 'What does an alternator use to produce an alternating current?', 'A fixed coil carrying a steady current', 'A magnet held still inside a fixed coil', 'A coil rotating in a magnetic field, with a split-ring commutator', 'A coil rotating in a magnetic field, with slip rings', 'D', 'An alternator uses slip rings so the current reverses every half turn. A dynamo uses a split-ring commutator to give direct current.', 'higher', 'recall', 'AO1'),
  (139, 'Induced potential, generators and transformers', 'A transformer has 200 turns on its primary coil and 800 turns on its secondary coil. The primary pd is 12 V. What is the secondary pd?', '12 V', '48 V', '3.0 V', '9600 V', 'B', 'Vs = Vp × Ns ÷ Np = 12 × 800 ÷ 200 = 48 V.', 'foundation', 'calculation', 'AO2'),
  (140, 'Permanent and induced magnetism and magnetic fields', 'How can you plot the magnetic field lines around a bar magnet?', 'Hold a thermometer near it and record the temperature', 'Place an ammeter near it and record the current', 'Sprinkle salt grains around it and watch them dissolve', 'Move a plotting compass around it and mark the needle''s direction', 'D', 'A plotting compass lines up with the field. Marking its direction at many points and joining them shows the field lines.', 'foundation', 'recall', 'AO1'),
  (141, 'Permanent and induced magnetism and magnetic fields', 'What happens to an induced magnet when it is taken out of the magnetic field?', 'It becomes more strongly magnetised', 'Its north and south poles swap', 'It becomes a permanent magnet', 'It loses most or all of its magnetism', 'D', 'An induced magnet is only a magnet while it is in a magnetic field.', 'foundation', 'recall', 'AO1'),
  (142, 'Orbital motion, natural and artificial satellites', 'A satellite''s speed changes. What must happen for it to stay in a stable orbit?', 'Its mass must change', 'Its speed must drop to zero', 'Its orbit radius must change', 'Its direction must reverse', 'C', 'For a stable orbit, the speed and radius are linked: a faster satellite must be in a smaller orbit.', 'higher', 'applied', 'AO3'),
  (143, 'Orbital motion, natural and artificial satellites', 'What is an artificial satellite?', 'A man-made object placed in orbit', 'A moon that orbits a planet', 'A planet that orbits the Sun', 'A star that orbits a galaxy', 'A', 'Artificial satellites are made and launched by people. Moons are natural satellites.', 'foundation', 'recall', 'AO1'),
  (144, 'Red-shift and the Big Bang', 'A galaxy is moving away from the Earth. How does the wavelength of light we receive from it compare with light from the same source at rest?', 'It is longer', 'It is the same', 'It is shorter', 'It is zero', 'A', 'Light from a receding galaxy is stretched to longer wavelengths (shifted towards red).', 'foundation', 'applied', 'AO2'),
  (145, 'Red-shift and the Big Bang', 'When would scientists change the Big Bang theory?', 'If new evidence does not fit it', 'When enough scientists vote to change it', 'After a fixed number of years has passed', 'When the universe stops expanding', 'A', 'Scientific theories change when new observations can''t be explained by the current theory, for example the discovery that the expansion is speeding up.', 'foundation', 'applied', 'AO3')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.name = v.sub
join topics t on t.id = s.topic_id
join subjects j on j.id = t.subject_id and j.name = 'Physics'
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

-- One quiz per subtopic (quizzes.subtopic_id set), holding every active
-- question in the subtopic, oldest first. Skips a subtopic that already has one.
with v(sub, title, ord) as (values
  ('Conservation, dissipation and efficiency', 'Conservation, dissipation and efficiency quiz', 14),
  ('Energy stores and calculating energy changes', 'Energy stores and calculating energy changes quiz', 11),
  ('National and global energy resources', 'National and global energy resources quiz', 15),
  ('Power', 'Power quiz', 13),
  ('Specific heat capacity', 'Specific heat capacity quiz', 12),
  ('Charge and current', 'Charge and current quiz', 11),
  ('Domestic uses and safety', 'Domestic uses and safety quiz', 14),
  ('Power, energy transfers and the National Grid', 'Power, energy transfers and the National Grid quiz', 15),
  ('Resistance and I-V characteristics', 'Resistance and I-V characteristics quiz', 12),
  ('Series and parallel circuits', 'Series and parallel circuits quiz', 13),
  ('Static electricity', 'Static electricity quiz', 16),
  ('Density and changes of state', 'Density and changes of state quiz', 11),
  ('Atoms, isotopes and the development of the atomic model', 'Atoms, isotopes and the development of the atomic model quiz', 11),
  ('Background radiation, uses of radiation, fission and fusion', 'Background radiation, uses of radiation, fission and fusion quiz', 14),
  ('Half-life, contamination and irradiation', 'Half-life, contamination and irradiation quiz', 13),
  ('Radioactive decay, nuclear radiation and nuclear equations', 'Radioactive decay, nuclear radiation and nuclear equations quiz', 12),
  ('Describing motion: speed, velocity, acceleration and graphs', 'Describing motion: speed, velocity, acceleration and graphs quiz', 16),
  ('Forces and elasticity', 'Forces and elasticity quiz', 13),
  ('Moments, levers and gears', 'Moments, levers and gears quiz', 14),
  ('Momentum', 'Momentum quiz', 19),
  ('Newton''s laws of motion', 'Newton''s laws of motion quiz', 17),
  ('Pressure in fluids', 'Pressure in fluids quiz', 15),
  ('Scalars, vectors, weight and resultant forces', 'Scalars, vectors, weight and resultant forces quiz', 11),
  ('Stopping distances', 'Stopping distances quiz', 18),
  ('Work done and energy transfer', 'Work done and energy transfer quiz', 12),
  ('Black body radiation', 'Black body radiation quiz', 16),
  ('Electromagnetic waves: properties, uses and hazards', 'Electromagnetic waves: properties, uses and hazards quiz', 13),
  ('Lenses', 'Lenses quiz', 14),
  ('Reflection, sound, ultrasound and seismic waves', 'Reflection, sound, ultrasound and seismic waves quiz', 12),
  ('Transverse and longitudinal waves and the wave equation', 'Transverse and longitudinal waves and the wave equation quiz', 11),
  ('Visible light and colour', 'Visible light and colour quiz', 15),
  ('Electromagnetism and the motor effect', 'Electromagnetism and the motor effect quiz', 12),
  ('Induced potential, generators and transformers', 'Induced potential, generators and transformers quiz', 13),
  ('Permanent and induced magnetism and magnetic fields', 'Permanent and induced magnetism and magnetic fields quiz', 11),
  ('Orbital motion, natural and artificial satellites', 'Orbital motion, natural and artificial satellites quiz', 12),
  ('Red-shift and the Big Bang', 'Red-shift and the Big Bang quiz', 13),
  ('The solar system and the life cycle of a star', 'The solar system and the life cycle of a star quiz', 11)
), ins as (
  insert into quizzes (topic_id, subtopic_id, title, display_order, question_count, cooldown_hours)
  select t.id, s.id, v.title, v.ord, 0, 168
  from v
  join subtopics s on s.name = v.sub
  join topics t on t.id = s.topic_id
  join subjects j on j.id = t.subject_id and j.name = 'Physics'
  where not exists (select 1 from quizzes z where z.subtopic_id = s.id)
  returning id, subtopic_id
)
insert into quiz_questions (quiz_id, question_id, position)
select ins.id, q.id, row_number() over (partition by ins.id order by q.created_at, q.id)
from ins join questions q on q.subtopic_id = ins.subtopic_id and q.active;

update quizzes z set question_count = (select count(*) from quiz_questions qq join questions q on q.id = qq.question_id where qq.quiz_id = z.id and q.active)
where z.subtopic_id is not null and z.question_count = 0;
commit;
